<?php require __DIR__.'/includes/bootstrap.php'; $title='Subscribe'; $message=''; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$consent=isset($_POST['consent'])?1:0;if(!$pdo)$error='Newsletter service is temporarily unavailable.';elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$error='Enter a valid email address.';elseif(!$consent)$error='Please confirm your consent to receive emails.';else{try{$s=$pdo->prepare('INSERT INTO subscribers(name,email,consent) VALUES(?,?,1)');$s->execute([$name,$email]);$message='Thank you for subscribing.';}catch(PDOException $e){$message=$e->getCode()==='23000'?'This email is already subscribed.':'Unable to complete your subscription.';}}}require __DIR__.'/includes/header.php';?><div class="container"><section class="card" style="max-width:620px;margin-inline:auto"><h1>Get Calmer Content in Your Inbox</h1><p class="muted">Receive occasional ASMR guides, sleep sound updates and equipment tips.</p><?php if($error):?><p role="alert"><?=e($error)?></p><?php endif;?><?php if($message):?><p role="status"><?=e($message)?></p><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><p><label>Name (optional)<input name="name" maxlength="120" autocomplete="name"></label></p><p><label>Email<input type="email" name="email" required maxlength="190" autocomplete="email"></label></p><p><label><input type="checkbox" name="consent" required> I agree to receive emails from ASMR Audio Online.</label></p><button type="submit">Subscribe</button></form></section></div><?php require __DIR__.'/includes/footer.php';
